package com.hotel.controller;
import com.hotel.dao.impl.UserDaoImpl; import com.hotel.dto.SessionUser; import com.hotel.service.AuthService; import jakarta.servlet.*; import jakarta.servlet.annotation.WebServlet; import jakarta.servlet.http.*; import java.io.IOException;
@WebServlet("/login") public class LoginServlet extends HttpServlet { private final AuthService auth=new AuthService(new UserDaoImpl()); protected void doGet(HttpServletRequest q,HttpServletResponse s)throws ServletException,IOException{q.getRequestDispatcher("/WEB-INF/views/login.jsp").forward(q,s);} protected void doPost(HttpServletRequest q,HttpServletResponse s)throws ServletException,IOException{SessionUser u=auth.authenticate(q.getParameter("email"),q.getParameter("password"));if(u==null){q.setAttribute("error","Invalid email, password, or account status.");doGet(q,s);return;}q.getSession(true).setAttribute("sessionUser",u);s.sendRedirect(q.getContextPath()+("RECEPTIONIST".equals(u.roleCode())?"/receptionist/customers":"/"));} }
